<script setup lang="ts">
import { onUnmounted, ref, watch } from "vue";
import { createSmsParserClient } from "../../workers/smsParserClient";
import type { SmsParserEdit } from "../../workers/smsParser.worker";
import { type SmsOriginCapabilities, type SmsParserDefinition, type SmsLiteralAmountRelation } from "@papilio/api";
const props=defineProps<{capabilities:SmsOriginCapabilities;disabled:boolean}>();
const model=defineModel<string>({required:true});
type LiteralField="credit_markers"|"debit_markers"|"clause_separators"|"reference_labels"|"rial_labels"|"toman_labels"|"grouping_separators";
type RelationField="deposit_relations"|"balance_relations";
const fields:{key:LiteralField;label:string}[]=[{key:"credit_markers",label:"Credit markers"},{key:"debit_markers",label:"Debit markers (take precedence)"},{key:"clause_separators",label:"Clause separators"},{key:"reference_labels",label:"Bank reference labels"},{key:"rial_labels",label:"Rial currency labels"},{key:"toman_labels",label:"Toman currency labels"},{key:"grouping_separators",label:"Digit grouping separators"}];
const relations:{key:RelationField;label:string}[]=[{key:"deposit_relations",label:"Deposit amount rules"},{key:"balance_relations",label:"Balance amount rules"}];
const data=ref<SmsParserDefinition|null>(null),validationError=ref(""),processing=ref(false);
const client=createSmsParserClient();let alive=true,sequence=0;
async function parse():Promise<void>{const key=++sequence;processing.value=true;validationError.value="";try{const reply=await client.compute({text:model.value,capabilities:props.capabilities});if(!alive||key!==sequence)return;data.value=reply.value;validationError.value=reply.error??"";}catch(cause){if(alive&&key===sequence)validationError.value=cause instanceof Error?cause.message:"Parser validation failed.";}finally{if(alive&&key===sequence)processing.value=false;}}
async function change(edit:SmsParserEdit):Promise<void>{if(props.disabled||processing.value||!data.value)return;const key=++sequence;processing.value=true;try{const reply=await client.compute({text:model.value,edit,capabilities:props.capabilities});if(!alive||key!==sequence)return;if(reply.text!==null)model.value=reply.text;else validationError.value=reply.error??"The parser definition could not be updated.";}catch(cause){if(alive&&key===sequence)validationError.value=cause instanceof Error?cause.message:"Parser update failed.";}finally{if(alive&&key===sequence)processing.value=false;}}
function text(event:Event):string{return (event.target as HTMLInputElement).value;}
function literal(key:LiteralField,index:number,event:Event):void{void change({field:key,operation:"set",index,value:text(event)});}
function addLiteral(key:LiteralField):void{if(!props.capabilities.capacity||!data.value||data.value[key].length>=props.capabilities.capacity.max_rules_per_field)return;void change({field:key,operation:"add",value:""});}
function addRelation(key:RelationField):void{if(!props.capabilities.capacity||!data.value||data.value[key].length>=props.capabilities.capacity.max_rules_per_field)return;void change({field:key,operation:"add",value:{marker:"",relation:props.capabilities.amount_relations[0]!,implicit_unit:null}});}
function rule(key:RelationField,index:number,field:keyof SmsLiteralAmountRelation,event:Event):void{const input=text(event);void change({field:key,operation:"set",index,member:field,value:field==="implicit_unit"&&input===""?null:input});}
watch(model,parse,{immediate:true});onUnmounted(()=>{alive=false;++sequence;client.close();});
</script>
<template>
<section v-if="data" class="form-grid" aria-label="Literal parser rules"><label class="field"><span>Parser mode</span><select :value="data.mode" :disabled="processing||disabled" @change="change({field:'mode',operation:'set',value:text($event)})"><option v-for="mode in capabilities.parser_modes" :key="mode" :value="mode">{{mode==='labelled_credit'?'Labelled credit amounts':'Legacy strict bank reference'}}</option></select></label><label class="check-row"><input :checked="data.case_sensitive" type="checkbox" :disabled="processing||disabled" @change="change({field:'case_sensitive',operation:'set',value:($event.target as HTMLInputElement).checked})"/>Match letter case exactly</label><section v-for="field in fields" :key="field.key" class="rule-section"><h4>{{field.label}}</h4><div v-for="(entry,index) in data[field.key]" :key="index" class="literal-row"><label class="field"><span>{{field.label}} {{index+1}}</span><textarea :value="entry" :maxlength="capabilities.capacity?.max_marker_chars" :disabled="processing||disabled" rows="1" required @input="literal(field.key,index,$event)"/></label><button type="button" class="btn small secondary" :disabled="processing||disabled" :aria-label="'Remove '+field.label+' '+(index+1)" @click="change({field:field.key,operation:'remove',index})">Remove</button></div><button type="button" class="btn small secondary" :disabled="processing||disabled||!capabilities.capacity||data[field.key].length>=capabilities.capacity.max_rules_per_field" @click="addLiteral(field.key)">Add literal</button></section><section v-for="field in relations" :key="field.key" class="rule-section"><h4>{{field.label}}</h4><div v-for="(entry,index) in data[field.key]" :key="index" class="form-grid amount-rule"><label class="field"><span>Literal label {{index+1}}</span><input :value="entry.marker" :maxlength="capabilities.capacity?.max_marker_chars" :disabled="processing||disabled" required @input="rule(field.key,index,'marker',$event)"/></label><label class="field"><span>Amount position</span><select :value="entry.relation" :disabled="processing||disabled" @change="rule(field.key,index,'relation',$event)"><option v-for="relation in capabilities.amount_relations" :key="relation" :value="relation">{{relation==='label_before_amount'?'Label before amount':'Amount before label'}}</option></select></label><label class="field"><span>Missing currency token</span><select :value="entry.implicit_unit??''" :disabled="processing||disabled" @change="rule(field.key,index,'implicit_unit',$event)"><option value="">Require explicit currency</option><option v-for="unit in capabilities.units" :key="unit" :value="unit">Use {{unit}} for this rule</option></select></label><button type="button" class="btn small secondary" :disabled="processing||disabled" @click="change({field:field.key,operation:'remove',index})">Remove rule</button></div><button type="button" class="btn small secondary" :disabled="processing||disabled||!capabilities.capacity||data[field.key].length>=capabilities.capacity.max_rules_per_field" @click="addRelation(field.key)">Add amount rule</button></section></section>
<p v-if="processing" role="status">Validating parser definition…</p><p v-else-if="validationError" class="message error" role="alert">{{validationError}}</p><p class="hint-box">Clause separators are literal text. A line break is a real separator; the advanced JSON editor represents it as \n. It is preserved when saving.</p>
</template>
<style scoped>.rule-section{border-top:1px solid var(--line);padding-top:12px}.literal-row{display:flex;align-items:end;gap:10px}.literal-row .field{flex:1;min-width:0}.amount-rule{padding:12px;margin-bottom:12px;border:1px solid var(--line);border-radius:var(--radius,12px)}</style>
